body:
Confirmed that the text `CalculatedSize` is as expected out of `text_system()` with the following minimal example. So this might be a bug in Taffy?

Screenshot on a high-DPI @ 150% scaling, purple box is 67px tall, but `CalculatedSize` of text itself is only 48px tall.

![image](https://user-images.githubusercontent.com/6532395/187531238-1fe08ac8-2d8f-49d5-b40d-9eb32206c04e.png)

```rust
use bevy::{
    diagnostic::{Diagnostics, FrameTimeDiagnosticsPlugin},
    prelude::*,
};

fn main() {
    App::new()
        .add_plugins(DefaultPlugins)
        .add_plugin(FrameTimeDiagnosticsPlugin::default())
        .insert_resource(bevy::log::LogSettings {
            level: bevy::log::Level::WARN,
            filter: "bevy_ui=trace".to_string(),
        })
        .add_startup_system(setup)
        .run();
}

fn setup(mut commands: Commands, asset_server: Res<AssetServer>) {
    // UI camera
    commands.spawn_bundle(Camera2dBundle::default());
    // Text with one section
    commands
        .spawn_bundle(NodeBundle {
            style: Style {
                position_type: PositionType::Absolute, // avoid interaction with other UI items if any
                flex_direction: FlexDirection::ColumnReverse, // top to bottom
                justify_content: JustifyContent::FlexStart, // align top
                position: UiRect {
                    left: Val::Percent(30.0),
                    right: Val::Percent(30.0),
                    bottom: Val::Px(30.),
                    ..default()
                },
                padding: UiRect::all(Val::Px(10.)),
                size: Size::new(Val::Auto, Val::Px(90.)),
                ..default()
            },
            color: UiColor(Color::rgb_u8(42, 42, 42)),
            ..default()
        })
        .with_children(|parent| {
            parent
                .spawn_bundle(NodeBundle {
                    style: Style {
                        flex_direction: FlexDirection::ColumnReverse, // top to bottom
                        align_items: AlignItems::FlexStart,           // align content top
                        ..default()
                    },
                    color: UiColor(Color::rgba_u8(122, 47, 125, 214)),
                    ..default()
                })
                .with_children(|parent| {
                    parent.spawn_bundle(
                        // Create a TextBundle that has a Text with a single section.
                        TextBundle::from_section(
                            // Accepts a `String` or any type that converts into a `String`, such as `&str`
                            "hello bevy! this is a text",
                            TextStyle {
                                font: asset_server.load("fonts/FiraSans-Bold.ttf"),
                                font_size: 32.0,
                                color: Color::WHITE,
                            },
                        ) // Set the alignment of the Text
                        .with_text_alignment(TextAlignment::TOP_CENTER)
                        // Set the style of the TextBundle itself.
                        .with_style(Style {
                            align_self: AlignSelf::FlexStart,
                            size: Size::new(Val::Px(400.), Val::Auto),
                            ..default()
                        }),
                    );
                });
        });
}
```

issue.body:
**Bevy version**

v0.4.0

**Operating system & version**

macOS 10.15.7

**What you did**

```rust
use bevy::prelude::*;

fn main() {
    App::build()
        .add_plugins(DefaultPlugins)
        .add_startup_system(setup.system())
        .run();
}

fn setup(commands: &mut Commands, asset_server: Res<AssetServer>) {
    commands
        .spawn(CameraUiBundle::default())
        .spawn(TextBundle {
            text: Text {
                value: "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Maecenas auctor, nunc ac faucibus fringilla.".to_string(),
                font: asset_server.load("fonts/FiraSans-Bold.ttf"),
                style: TextStyle {
                    font_size: 60.0,
                    color: Color::WHITE,
                    ..Default::default()
                },
            },
            style: Style {
                position_type: PositionType::Absolute,
                position: Rect {
                    left: Val::Px(0.0),
                    top: Val::Px(0.0),
                    ..Default::default()
                },
                max_size: Size::new(Val::Percent(50.0), Val::Percent(100.0)),
                ..Default::default()
            },
            ..Default::default()
        });
}
```

**What you expected to happen**

I expected it to wrap the text at half the window width.

**What actually happened**

It doesn't wrap the text.  It runs right up to the right edge of the window.

**Additional information**

It seems that setting a `max_size` with `Val::Px()` works, but percent doesn't.
